import type { SecretRef } from "@getdonn/adapter-sdk";

// Secrets and the env names generated files read. See docs/planning/24-adapter-eve.md, sections 2
// and 3 ("Secrets in headers"), and the file this builds, `agent/lib/donn/env.ts`.

export const ENV_FILE = "agent/lib/donn/env.ts";

/** A secret ref in a string: it ends at whitespace, a quote or a character a URL or list uses. */
const REF_PATTERN = "secret:\\/\\/[^\\s\"'`;&?#),]+";
const REF = new RegExp(REF_PATTERN, "g");

/** The whole-value form of a ref, as `@getdonn/secrets` reads it: `secret://<provider>/<path>`. */
const WHOLE_REF = /^secret:\/\/[^/]+\/.+$/;

/** Whether `value` is one secret ref in full (a path may hold `,` `?` `#` and the like). */
export const isWholeRef = (value: string) => WHOLE_REF.test(value);

/**
 * Hands out `DONN_SECRET_<n>` for each secret ref: `n` counts from 1 in the order refs are first
 * asked for, and the same ref keeps its number. The compile asks in one fixed walk (the gateway's
 * base URL, key, then headers by name; then each connection by name: its url, then its headers by
 * name, a bearer token in its place), so the numbers depend only on the persona.
 */
export class SecretNames {
  readonly #byRef = new Map<SecretRef, string>();

  name(ref: string): string {
    const known = this.#byRef.get(ref as SecretRef);
    if (known !== undefined) return known;
    const name = `DONN_SECRET_${this.#byRef.size + 1}`;
    this.#byRef.set(ref as SecretRef, name);
    return name;
  }

  /** Placeholder env var → secret ref, in numbering order. */
  toSecretEnv(): Record<string, SecretRef> {
    return Object.fromEntries(
      [...this.#byRef].map(([ref, name]) => [name, ref]),
    );
  }
}

const escapeTemplate = (text: string) =>
  text.replace(/[\\`]|\$\{/g, (match) => `\\${match}`);

/**
 * A TypeScript expression for a string that may embed secret refs: a JSON string when there are
 * none, the env read when the whole value is one ref, else a template literal around the reads.
 */
export function valueExpression(value: string, secrets: SecretNames): string {
  // A value that starts with a ref is that ref to its end, as the SDK and the secret providers
  // read it; the delimiters of REF only bound a ref embedded in a longer string.
  if (isWholeRef(value)) return `process.env.${secrets.name(value)}!`;
  const refs = [...value.matchAll(REF)];
  if (refs.length === 0) return JSON.stringify(value);
  let out = "";
  let at = 0;
  for (const match of refs) {
    out += escapeTemplate(value.slice(at, match.index));
    out += `\${process.env.${secrets.name(match[0])}}`;
    at = match.index + match[0].length;
  }
  return `\`${out}${escapeTemplate(value.slice(at))}\``;
}

/** An object key: bare when it is an identifier, else quoted. */
export const propertyKey = (key: string) =>
  /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(key) ? key : JSON.stringify(key);

/**
 * `agent/lib/donn/env.ts`: reads every env name donn's files rely on. Loading it never throws
 * (`eve build` evaluates agent modules without the run-time environment); it warns once naming
 * the missing ones, and `config.ts` makes the model refuse to run until `missingEnv()` is empty.
 * A variable set to the empty string counts as present.
 */
export function envFile(
  names: readonly string[],
  anyOf: readonly (readonly string[])[] = [],
): string {
  const sorted = [...new Set(names)].sort();
  const body = sorted.map((name) => `  ${name}: process.env.${name},`);
  const groups = anyOf.map((group) => [...new Set(group)].sort());
  return [
    "// Generated by donn; edit the persona, not this file.",
    "// The environment variables donn's generated files read. Loading this module only warns;",
    "// the agent's model refuses to run while any is missing (see config.ts).",
    "const values: Record<string, string | undefined> = {",
    ...body,
    "};",
    ...(groups.length > 0
      ? [
          "",
          "// Each group is satisfied by any one of its variables.",
          "const anyOf: Record<string, string | undefined>[] = [",
          ...groups.map(
            (group) =>
              `  { ${group.map((name) => `${name}: process.env.${name}`).join(", ")} },`,
          ),
          "];",
        ]
      : []),
    "",
    "export function missingEnv(): string[] {",
    groups.length > 0
      ? "  const missing = Object.keys(values).filter((name) => values[name] === undefined);"
      : "  return Object.keys(values).filter((name) => values[name] === undefined);",
    ...(groups.length > 0
      ? [
          "  for (const group of anyOf) {",
          "    if (Object.values(group).every((value) => value === undefined)) {",
          '      missing.push(Object.keys(group).join(" or "));',
          "    }",
          "  }",
          "  return missing;",
        ]
      : []),
    "}",
    "",
    "const missing = missingEnv();",
    "if (missing.length > 0) {",
    '  console.warn(`donn: missing environment variables: ${missing.join(", ")}`);',
    "}",
    "",
  ].join("\n");
}
